 soundAction.Sound.Bits = 16;
 soundAction.Sound.Channels = PdfSoundChannels.Stereo;
 soundAction.Sound.Encoding = PdfSoundEncoding.Signed;
 soundAction.Volume = 0.9f;
 soundAction.Mix = true;
