rendermode.Style = Pdf3DRenderStyle.Solid;
rendermode.AuxilaryColor = new PdfColor(Color.Green);
rendermode.FaceColor = new PdfColor(Color.Black);
PdfColor color = new PdfColor(Color.Silver);
