comp.Brush = brush
comp.Location = New PointF(100, 100)
comp.Draw(mainPage.Graphics)
comp.Size = New SizeF(300, 300)
comp.Font = font
'Save and close the document.
document.Save("Output.pdf")
document.Close(True)


