Dim standardFont As PdfFont = New PdfStandardFont(PdfFontFamily.TimesRoman,10)
'Drawing string on the page.
pageCollection(0).Graphics.DrawString("FirstPage", standardFont, PdfBrushes.Black, New PointF(10, 10))
'Save the document.
doc.Save("Output.pdf")
'Close the document.
doc.Close(True)


