example.code:
PdfDocument pdfDoc = new PdfDocument();
PdfPage page = pdfDoc.Pages.Add();
// Get xmp object.
XmpMetadata xmp = pdfDoc.DocumentInformation.XmpMetadata;
// XMP Basic Schema.
BasicSchema basic = xmp.BasicSchema;
basic.Advisory.Add("advisory");
basic.BaseURL = new Uri("http://google.com");
basic.CreateDate = DateTime.Now;
basic.CreatorTool = "creator tool";
basic.Identifier.Add("identifier");
basic.Label = "label";
basic.MetadataDate = DateTime.Now;
basic.ModifyDate = DateTime.Now;
basic.Nickname = "nickname";
basic.Rating.Add(-25);
pdfDoc.Save("DocumentInformation.pdf");
pdfDoc.Close(true);

members.member:

This class represents a set of the properties that define the internal structure of PDF file.



//Create a new document
PdfDocument doc = new PdfDocument();
//Create a new page
PdfPage page = doc.Pages.Add();
//Create new instance for PDF file structure.
PdfFileStructure structure = new PdfFileStructure();
//Set the file structure cross reference type.
structure.CrossReferenceType = PdfCrossReferenceType.CrossReferenceStream;
//Set the document`s file structure.
doc.FileStructure = structure;
// Save the document
doc.Save("FileStructure.pdf");
doc.Close(true);


'Create a new document
Dim doc As New PdfDocument()
'Create a new page
Dim page As PdfPage = doc.Pages.Add()
'Create new instance for PDF file structure.
Dim pdfstructure As PdfFileStructure = New PdfFileStructure()
'Set the file structure cross reference type
pdfstructure.CrossReferenceType = PdfCrossReferenceType.CrossReferenceStream
'Set the document`s file structure
doc.FileStructure = pdfstructure
'Save the document
doc.Save("FileStructure.pdf")
doc.Close(True)


