//Add field to form.
document.Form.Fields.Add(textBox);
//Enable complex script
document.Form.ComplexScript = true;
document.Form.SetDefaultAppearance(false)
//Save the document.
document.Save("output.pdf");
//Close the document.
document.Close(true);

