format.Layout = PdfLayoutType.Paginate;
//Set paginate bounds.
format.PaginateBounds = new RectangleF(0, 0, 500, 350);
//Draw grid to the page of PDF document.
table.Draw(page, new RectangleF(0,0, 500, 700), format);
//Save the document.
doc.Save("Output.pdf");
//close the document
doc.Close(true);

