member.summary:
Colors are represented solely with respect to the light source;
no correction is made for the output mediums white point
(such as the color of unprinted paper).

example.code:
// Create a PDF Document.
PdfDocument doc = new PdfDocument();
//Add pages to the document
PdfPage page = doc.Pages.Add();
//Create PDF graphics for the page
PdfGraphics graphics = page.Graphics;
//Create PDF font.
PdfFont font = new PdfStandardFont(PdfFontFamily.Helvetica, 12, PdfFontStyle.Regular);
//Set transparancy.
graphics.SetTransparency(0.5f, 0.5f, PdfBlendMode.HardLight);
//Draws the String.
graphics.DrawString("Hello world!", font, PdfPens.Black, PdfBrushes.Red, 0, 0);        
//Save the document
doc.Save("Output.pdf");
//Close the document
doc.Close(true);

//Create a new PDF document.
PdfDocument doc = new PdfDocument();
//Add a page to the document.
PdfPage page = doc.Pages.Add();
//Create PDF graphics for the page
PdfGraphics graphics = page.Graphics;
string rtfData = @"{\rtf1\ansi\deff0 {\colortbl;\red0\green0\blue0;\red255\green0\blue0; }Default Color\line\cf2Red Color\line\cf1Default Color}";
//Load image from rtf data.
PdfImage image = PdfImage.FromRtf(rtfData, 200, PdfImageType.Bitmap)
//Draw the image
graphics.DrawImage(image, 0, 0);
//Save the document.
doc.Save("Output.pdf");
//Close the document.
doc.Close(true);

