//Create a new PDF document.
PdfDocument doc = new PdfDocument();
//Add a page.
PdfPage page = doc.Pages.Add();
//Create a PdfGrid.
PdfGrid pdfGrid = new PdfGrid();
//Create a DataTable.
DataTable dataTable = new DataTable("EmpDetails");
//Add columns to the DataTable           
dataTable.Columns.Add("ID");
dataTable.Columns.Add("Name");
//Add rows to the DataTable.
dataTable.Rows.Add(new object[] { "E01", "Clay" });
dataTable.Rows.Add(new object[] { "E02", "Thomas" });
//Assign data source.
pdfGrid.DataSource = dataTable;            
//PDF grid cell
PdfGridCell cell = pdfGrid.Rows[0].Cells[0];
//Set row span
cell.RowSpan = 2;
//set column span.
cell.ColumnSpan = 2;
//Check whether the text is HTML text?
bool isHtmlText = cell.IsHtmlText;
//Set Value.
cell.Value = "George";
//Set string format.
cell.StringFormat.Alignment = PdfTextAlignment.Center;
//Set image position.
cell.ImagePosition = PdfGridImagePosition.Fit;
//Set PDF tag.
cell.PdfTag = new PdfStructureElement(PdfTagType.TableDataCell);
//Set cell style.                 
cell.Style.BackgroundImage = new PdfBitmap("Autumn leaves.jpg");
//Draw grid to the page of PDF document.
pdfGrid.Draw(page, new PointF(10, 10));
//Save the document.
doc.Save("Output.pdf");
//close the document
doc.Close(true);

//Create new PDF document
PdfDocument doc = new PdfDocument();
//Add a new page
page = doc.Pages.Add();
//Set the dimension of the PDF page
float width = new PdfUnitConvertor().ConvertToPixels(page.GetClientSize().Width, PdfGraphicsUnit.Point);
float height = -1f;
//Initialize HTML to PDF converter
using (Syncfusion.HtmlConverter.HtmlConverter html = new Syncfusion.HtmlConverter.HtmlConverter())
{
//Convert the URL
HtmlToPdfResult result = html.Convert("http://www.syncfusion.com", ImageType.Metafile, (int)width, (int)height, AspectRatio.KeepWidth);
if (result != null)
{
//Get the HTML as PdfMetafile
PdfMetafile mf = new PdfMetafile(result.RenderedImage as Metafile);
//Formatting options
PdfMetafileLayoutFormat format = new PdfMetafileLayoutFormat();
format.Break = PdfLayoutBreakType.FitPage;
format.Layout = PdfLayoutType.Paginate;
doc.PageSettings.Height = result.RenderedImage.Size.Height;
format.SplitTextLines = false;
format.SplitImages = false;
//Render the PdfMetafile in the PDF document
result.Render(page, format);
}
}
//Save the PDF
doc.Save(@"Output.pdf");
//Close the PDF
doc.Close(true);

