Specifies the format of Export or Import data.



//Load an existing document
PdfLoadedDocument ldoc = new PdfLoadedDocument("SourceForm.pdf");
// Load the existing form
PdfLoadedForm form = ldoc.Form;
// Export the form data as XML file
form.ExportData("Export.xml", DataFormat.Xml, "SourceForm.pdf");


'Load an existing document
Dim ldoc As PdfLoadedDocument = New PdfLoadedDocument("SourceForm.pdf")
' Load the existing form
Dim form As PdfLoadedForm = ldoc.Form
' Export the form data as XML file
form.ExportData("Export.xml", DataFormat.Xml, "SourceForm.pdf")


 Class  
 Class


Represents a PdfLoadedDocument. You can use this class to load or modify an existing PDF document



// Loads an existing document
PdfLoadedDocument lDoc = new PdfLoadedDocument("Input.pdf");
lDoc.Save("Output.pdf");
lDoc.Close(true);


' Loads an existing document
Dim lDoc As PdfLoadedDocument = New PdfLoadedDocument("Input.pdf")
lDoc.Save("Output.pdf")
lDoc.Close(True)


 Class
 Class

A relative or absolute path for the file.
/// This constructor is not supported in WinRT, Windows Phone, Xamarin, Universal Windows Platform and Silverlight


// Loads an existing PDF Document
PdfLoadedDocument doc = new PdfLoadedDocument("Input.pdf");
// Save the document to a disk
doc.Save("Output.pdf");
doc.Close(true);


' Loads an existing PDF Document
Dim doc As PdfLoadedDocument = New PdfLoadedDocument("Input.pdf")
' Save the document to a disk
doc.Save("Output.pdf")
doc.Close(True)


 Class


Initializes a new instance of the  class with the specified input file path and repair document

A relative or absolute path for the file.
True to repair the document to prevent document corruption
This constructor loads the document and also repairs the wrong offsets. 
The repairing engine is not capable of fixing all kinds of corruption and the process may delay the loading time depending on the type of issue. This constructor is not supported in WinRT, Windows Phone, Xamarin, Universal Windows Platform and Silverlight. 


// Loads an existing PDF Document
PdfLoadedDocument doc = new PdfLoadedDocument("Input.pdf", true);
// Save the document to a disk
doc.Save("Output.pdf");
doc.Close(true);


' Loads an existing PDF Document
Dim doc As PdfLoadedDocument = New PdfLoadedDocument("Input.pdf", True)
' Save the document to a disk
doc.Save("Output.pdf")
doc.Close(True)


