void table_EndCellLayout(object sender, PdfGridEndCellLayoutEventArgs args)
{
  if (args.RowIndex == 1)
  {
    args.Graphics.DrawRectangle(new PdfPen(PdfBrushes.Red, 2), PdfBrushes.White, args.Bounds);
  }
}


