// Create a PDF document
PdfDocument document = new PdfDocument();
//Create a new page
PdfPage page = document.Pages.Add();
//Create table 
PdfLightTable table = new PdfLightTable();
//Set the DataSourceType as Direct
table.DataSourceType = PdfLightTableDataSourceType.TableDirect;
//Get the columns collection
PdfColumnCollection tableColumns = table.Columns;
//Creating Columns
PdfColumn name = new PdfColumn("Name");
name.Width = 10;
//Set second column
PdfColumn sirname = new PdfColumn("Sir name");
sirname.Width = 40;
//Set third column 
PdfColumn rollNumber = new PdfColumn("Roll Number");
rollNumber.StringFormat = new PdfStringFormat(PdfTextAlignment.Left);
rollNumber.Width = 20;
//Set table width
float tableWidth = 300;
//Enable the ColumnProportionalSizing based on table width 
table.ColumnProportionalSizing = true;
//Add the column
tableColumns.Add(name);
tableColumns.Add(sirname);
tableColumns.Add(rollNumber);
//Adding Rows
table.Rows.Add(new object[] { "Jan", "Hussaarts", "Developer" });
//Draw the table
table.Draw(page, 0, 0, tableWidth);
//Save the document
document.Save("Output.pdf");
//Close the document
document.Close(true);

