format.StartColumnIndex = 1;
format.EndColumnIndex = 2;    
// Draw the table
PdfLightTableLayoutResult result = table.Draw(page, new PointF(0, 0), format);
//Save the document.
document.Save("Output.pdf");
//Close the document
document.Close(true);

